"""SMT and formal verification models for PatchForge AI."""
from typing import List, Dict, Optional, Any
from pydantic import BaseModel, Field


class BoundaryConstraint(BaseModel):
    """Specific boundary constraint derived from AST analysis or Z3 solving."""
    variable_name: str
    constraint_type: str  # "INTEGER_BOUNDS", "ARRAY_INDEX", "STRING_LENGTH"
    lower_bound: Optional[int] = None
    upper_bound: Optional[int] = None
    z3_expression: Optional[str] = None


class FormalInvariant(BaseModel):
    """Formal safety invariants generated by the Z3 SMT solver."""
    predicate_formula: str
    z3_model_status: str  # "UNSAT" (safe), "SAT" (violation), "UNKNOWN", "VIOLATION_POSSIBLE", "UNCONDITIONALLY_SAFE"
    required_invariants: List[str] = Field(default_factory=list)
    counterexample: Optional[Dict[str, Any]] = None
    boundary_constraints: List[BoundaryConstraint] = Field(default_factory=list)


class Z3VerificationResult(BaseModel):
    """Full outcome of a Z3 SMT solver check."""
    is_safe: bool
    status: str
    counterexample: Optional[Dict[str, Any]] = None
    formula: str = ""
    invariant_rules: List[str] = Field(default_factory=list)

